WITH scored AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, LEAD(salary, 1) OVER (PARTITION BY job_title ORDER BY hire_date, id) AS next_salary, CUME_DIST() OVER (ORDER BY salary DESC) AS salary_cume_dist FROM employees) SELECT job_title, MAX(salary) AS max_salary, ROUND(SUM(salary_cume_dist) / NULLIF(COUNT(CASE WHEN job_title = 'Manager' THEN 1 END), 0), 2) AS salary_cume_dist_per_manager, ROUND(SUM(next_salary) / NULLIF(COUNT(CASE WHEN level = 'L2' THEN 1 END), 0), 2) AS next_salary_per_l2, COUNT_IF(job_title = 'Analyst') AS analyst_events FROM scored GROUP BY 1
